const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helper to promisify getInfo
  function getInfo(eeObj) {
    return new Promise((resolve, reject) => {
      eeObj.getInfo((v, e) => {
        if (e) reject(e);
        else resolve(v);
      });
    });
  }

  // Geometry & dates
  const borPoint = ee.Geometry.Point([31.56, 6.21]);
  const aoi = borPoint.buffer(25000).bounds(); // 25 km buffer box for consistent pixel counts
  const scale = 1000; // as required (>=1000)
  const maxPixels = 1e9;

  const date2019 = '2019-12-06';
  const date2021 = '2021-12-04';

  async function getS1Stats(targetDateStr) {
    const targetDate = ee.Date(targetDateStr);
    async function build(windowDays) {
      const start = targetDate.advance(-windowDays, 'day');
      const end = targetDate.advance(windowDays + 1, 'day');
      let col = ee.ImageCollection('COPERNICUS/S1_GRD')
        .filterBounds(aoi)
        .filterDate(start, end)
        .filter(ee.Filter.eq('instrumentMode', 'IW'))
        .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'));
      const size = await getInfo(col.size());
      if (size === 0) return { ok: false, size, windowDays };
      // Select median to reduce speckle
      const img = col.median().clip(aoi);
      const vvDb = img.select('VV').max(1e-6).log10().multiply(10).rename('vvDb');
      const water = vvDb.lt(-17.0); // threshold (dB)
      const validCount = await getInfo(vvDb.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale,
        maxPixels: maxPixels,
      }).get('vvDb')) || 0;
      const waterAreaM2 = await getInfo(ee.Image.pixelArea().updateMask(water).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: scale,
        maxPixels: maxPixels,
      }).get('area')) || 0;

      const colNear = col.map(function(im) {
        const d = ee.Date(im.get('system:time_start'));
        const diff = d.difference(targetDate, 'day').abs();
        return im.set('dateDist', diff);
      }).sort('dateDist');
      const closest = colNear.first();
      const closestDateStr = await getInfo(ee.Date(closest.get('system:time_start')).format('YYYY-MM-dd'));

      return {
        ok: true,
        source: 'S1',
        size,
        windowDays,
        thresholdDb: -17.0,
        closestDateStr,
        validCount: validCount || 0,
        waterAreaM2: waterAreaM2 || 0,
      };
    }
    let res = await build(10);
    if (!res.ok) res = await build(30);
    return res;
  }

  async function getS2Stats(targetDateStr) {
    const targetDate = ee.Date(targetDateStr);
    async function build(windowDays) {
      const start = targetDate.advance(-windowDays, 'day');
      const end = targetDate.advance(windowDays + 1, 'day');
      let col = ee.ImageCollection('COPERNICUS/S2_SR')
        .filterBounds(aoi)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 85));
      const size = await getInfo(col.size());
      if (size === 0) return { ok: false, size, windowDays };

      const median = col.median().clip(aoi);
      const sclMode = col.select('SCL').mode().clip(aoi);
      const cloudMask = sclMode.eq(3).or(sclMode.eq(7)).or(sclMode.eq(8))
        .or(sclMode.eq(9)).or(sclMode.eq(10)).or(sclMode.eq(11));
      const validMask = cloudMask.not();

      const green = median.select('B3');
      const nir = median.select('B8');
      const denom = green.add(nir);
      const ndwi = green.subtract(nir).divide(denom).updateMask(denom.neq(0)).rename('NDWI').updateMask(validMask);
      const water = ndwi.gt(0.3);

      const validCount = await getInfo(ndwi.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale,
        maxPixels: maxPixels,
      }).get('NDWI')) || 0;

      const waterAreaM2 = await getInfo(ee.Image.pixelArea().updateMask(water).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: scale,
        maxPixels: maxPixels,
      }).get('area')) || 0;

      const totalPx = await getInfo(sclMode.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale,
        maxPixels: maxPixels,
      }).get('SCL')) || 0;

      const cloudPx = await getInfo(sclMode.updateMask(cloudMask).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale,
        maxPixels: maxPixels,
      }).get('SCL')) || 0;

      const cloudPct = totalPx > 0 ? (cloudPx / totalPx) * 100 : null;

      const colNear = col.map(function(im) {
        const d = ee.Date(im.get('system:time_start'));
        const diff = d.difference(targetDate, 'day').abs();
        return im.set('dateDist', diff);
      }).sort('dateDist');
      const closest = colNear.first();
      const closestDateStr = await getInfo(ee.Date(closest.get('system:time_start')).format('YYYY-MM-dd'));

      return {
        ok: true,
        source: 'S2',
        size,
        windowDays,
        closestDateStr,
        validCount: validCount || 0,
        waterAreaM2: waterAreaM2 || 0,
        cloudPct: cloudPct,
        ndwiThr: 0.3
      };
    }
    let res = await build(10);
    if (!res.ok) res = await build(30);
    return res;
  }

  async function getBestStats(dateStr) {
    let s1 = await getS1Stats(dateStr);
    if (s1.ok) return s1;
    let s2 = await getS2Stats(dateStr);
    if (s2.ok) return s2;
    return { ok: false, reason: 'No images in both S1 and S2 after expansions' };
  }

  try {
    console.log('AOI: Bor, South Sudan (25 km buffer), scale: 1000 m');
    console.log('Primary: Sentinel-1 VV dB < -17.0 (water); Fallback: Sentinel-2 NDWI > 0.3');

    const stats2019 = await getBestStats(date2019);
    const stats2021 = await getBestStats(date2021);

    if (!stats2019.ok || !stats2021.ok) {
      if (!stats2019.ok) console.log('2019-12-06: No images found (after ±30d).');
      if (!stats2021.ok) console.log('2021-12-04: No images found (after ±30d).');
      console.log('C1');
      return;
    }

    function fmtLine(tag, s) {
      const base = `${tag} ${s.closestDateStr || 'n/a'} | ${s.source} imgs:${s.size} (±${s.windowDays}d) | valid px:${s.validCount} | water km2:${(s.waterAreaM2/1e6).toFixed(2)}`;
      if (s.source === 'S2' && s.cloudPct != null) {
        return base + ` | cloud%:${s.cloudPct.toFixed(1)}`;
      }
      return base;
    }

    console.log('2019:', fmtLine(date2019, stats2019));
    console.log('2021:', fmtLine(date2021, stats2021));

    // C2: No valid pixels
    if ((stats2019.validCount || 0) === 0 || (stats2021.validCount || 0) === 0) {
      if ((stats2019.validCount || 0) === 0) console.log('2019: No valid pixels after masking.');
      if ((stats2021.validCount || 0) === 0) console.log('2021: No valid pixels after masking.');
      console.log('C2');
      return;
    }

    // C3: invalid calculation
    function invalid(v) {
      return v === null || v === undefined || !isFinite(v) || v < 0;
    }
    if (invalid(stats2019.waterAreaM2) || invalid(stats2021.waterAreaM2)) {
      console.log('Calculation failure (null/NaN/negative area).');
      console.log('C3');
      return;
    }

    const deltaKm2 = (stats2021.waterAreaM2 - stats2019.waterAreaM2) / 1e6;
    console.log(`Δ Water (2021-2019) km2: ${deltaKm2.toFixed(2)}`);

    // Final answer
    const answer = deltaKm2 > 0 ? 'A' : 'B';
    console.log(answer);
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
